const uid = () => (crypto.randomUUID ? crypto.randomUUID() : 'id-' + Math.random().toString(36).slice(2));
const nowLocal = () => {
  const d = new Date(), p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
};
const datePart = (s) => (s || '').slice(0, 10);
const todayStr = () => { const d = new Date(), p = (n) => String(n).padStart(2, '0'); return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`; };

const DEMO_USER = { ...data.users[0], password_hash: undefined };

function summary() {
  const t = todayStr();
  const fuPending = data.follow_ups.filter((f) => f.status === 'pending');
  const m = t.slice(0, 7);
  const dealsChot = data.deals.filter((d) => d.status === 'da_chot' && (d.closed_at || '').slice(0, 7) === m);
  return {
    leads_moi_hom_nay: data.leads.filter((l) => l.status === 'moi' && datePart(l.created_at) === t).length,
    followup_den_han: fuPending.filter((f) => datePart(f.due_at) === t).length,
    followup_qua_han: fuPending.filter((f) => datePart(f.due_at) < t).length,
    deals_thang: dealsChot.length,
    doanh_so_thang: dealsChot.reduce((s, d) => s + Number(d.value || 0), 0),
    followup_hom_nay: fuPending
      .filter((f) => datePart(f.due_at) === t)
      .sort((a, b) => a.due_at.localeCompare(b.due_at))
      .slice(0, 10)
      .map((f) => ({ ...f, lead_name: (data.leads.find((l) => l.id === f.lead_id) || {}).full_name })),
  };
}

function leadDetail(id) {
  const lead = data.leads.find((l) => l.id === id);
  if (!lead) throw new Error('Không tìm thấy lead');
  return {
    ...lead,
    follow_ups: data.follow_ups.filter((f) => f.lead_id === id).sort((a, b) => b.created_at.localeCompare(a.created_at)),
    activities: data.activities.filter((a) => a.lead_id === id).sort((a, b) => b.created_at.localeCompare(a.created_at)),
    deals: data.deals.filter((d) => d.lead_id === id),
  };
}

function dealsList() {
  return data.deals
    .map((d) => ({
      ...d,
      lead_name: (data.leads.find((l) => l.id === d.lead_id) || {}).full_name,
      property_code: (data.properties.find((p) => p.id === d.property_id) || {}).code,
    }))
    .sort((a, b) => b.created_at.localeCompare(a.created_at));
}

export async function mockApi(path, opts = {}) {
  const method = (opts.method || 'GET').toUpperCase();
  const body = opts.body ? JSON.parse(opts.body) : {};
  const [rawPath, query] = path.split('?');
  const q = Object.fromEntries(new URLSearchParams(query || ''));
  // giả lập độ trễ mạng nhẹ cho cảm giác thật
  await new Promise((r) => setTimeout(r, 120));

  // --- Auth ---
  if (rawPath === '/auth/login' && method === 'POST') {
    if (body.phone === '0901234567' && body.password === 'demo123456') {
      return { token: 'mock-jwt-demo-token', user: DEMO_USER };
    }
    throw new Error('SĐT hoặc mật khẩu chưa đúng (demo: 0901234567 / demo123456)');
  }

  // --- Dashboard ---
  if (rawPath === '/dashboard/summary') return summary();

  // --- Leads ---
  if (rawPath === '/leads' && method === 'GET') {
    let rows = [...data.leads].sort((a, b) => b.updated_at.localeCompare(a.updated_at));
    if (q.status) rows = rows.filter((l) => l.status === q.status);
    if (q.q) rows = rows.filter((l) => l.full_name.includes(q.q) || l.phone.includes(q.q));
    return rows;
  }
  if (rawPath === '/leads' && method === 'POST') {
    if (!body.full_name || !body.phone) throw new Error('Vui lòng nhập họ tên và số điện thoại');
    const now = nowLocal();
    const lead = { id: uid(), workspace_id: data.workspaces[0].id, owner_id: DEMO_USER.id, full_name: body.full_name, phone: body.phone, zalo: body.zalo || null, source: body.source || 'khac', demand_json: body.demand ? JSON.stringify(body.demand) : null, status: 'moi', score: body.score || 50, created_at: now, updated_at: now };
    data.leads.push(lead);
    return lead;
  }
  let m = rawPath.match(/^\/leads\/([^/]+)\/stage$/);
  if (m && method === 'PATCH') {
    const lead = data.leads.find((l) => l.id === m[1]);
    if (!lead) throw new Error('Không tìm thấy lead');
    const now = nowLocal();
    lead.status = body.status; lead.updated_at = now;
    data.activities.push({ id: uid(), lead_id: lead.id, owner_id: DEMO_USER.id, type: 'doi_trang_thai', content: `Chuyển trạng thái sang "${body.status}"`, created_at: now });
    return { ...lead };
  }
  m = rawPath.match(/^\/leads\/([^/]+)\/activities$/);
  if (m && method === 'GET') {
    return data.activities.filter((a) => a.lead_id === m[1]).sort((a, b) => b.created_at.localeCompare(a.created_at));
  }
  m = rawPath.match(/^\/leads\/([^/]+)$/);
  if (m && method === 'GET') return leadDetail(m[1]);
  if (m && method === 'PATCH') {
    const lead = data.leads.find((l) => l.id === m[1]);
    if (!lead) throw new Error('Không tìm thấy lead');
    Object.assign(lead, body, { updated_at: nowLocal() });
    return { ...lead };
  }

  // --- Follow-ups ---
  if (rawPath === '/follow-ups' && method === 'GET') {
    const t = todayStr();
    let rows = data.follow_ups.filter((f) => f.status === 'pending');
    if (q.filter === 'today') rows = rows.filter((f) => datePart(f.due_at) === t);
    else if (q.filter === 'overdue') rows = rows.filter((f) => datePart(f.due_at) < t);
    else if (q.filter === 'upcoming') rows = rows.filter((f) => datePart(f.due_at) > t);
    return rows.sort((a, b) => a.due_at.localeCompare(b.due_at)).map((f) => ({ ...f, lead_name: (data.leads.find((l) => l.id === f.lead_id) || {}).full_name }));
  }
  if (rawPath === '/follow-ups' && method === 'POST') {
    if (!body.title) throw new Error('Vui lòng nhập nội dung lịch chăm sóc');
    const now = nowLocal();
    const fu = { id: uid(), lead_id: body.lead_id || null, owner_id: DEMO_USER.id, title: body.title, due_at: body.due_at || now, note: body.note || '', status: 'pending', created_at: now };
    data.follow_ups.push(fu);
    return fu;
  }
  m = rawPath.match(/^\/follow-ups\/([^/]+)\/complete$/);
  if (m && method === 'POST') {
    const fu = data.follow_ups.find((f) => f.id === m[1]);
    if (!fu) throw new Error('Không tìm thấy lịch chăm sóc');
    fu.status = 'done';
    return { ok: true };
  }

  // --- Activities ---
  if (rawPath === '/activities' && method === 'POST') {
    if (!body.content) throw new Error('Vui lòng nhập nội dung');
    const act = { id: uid(), lead_id: body.lead_id, owner_id: DEMO_USER.id, type: body.type || 'ghi_chu', content: body.content, created_at: nowLocal() };
    data.activities.push(act);
    return act;
  }

  // --- Projects ---
  if (rawPath === '/projects' && method === 'GET') return [...data.projects];
  m = rawPath.match(/^\/projects\/([^/]+)$/);
  if (m && method === 'GET') {
    const project = data.projects.find((p) => p.id === m[1]);
    if (!project) throw new Error('Không tìm thấy dự án');
    return { ...project, properties: data.properties.filter((p) => p.project_id === m[1]), documents: data.documents.filter((d) => d.project_id === m[1]) };
  }

  // --- Deals ---
  if (rawPath === '/deals' && method === 'GET') return dealsList();
  if (rawPath === '/deals' && method === 'POST') {
    if (!body.lead_id || !body.value) throw new Error('Vui lòng chọn khách hàng và nhập giá trị');
    const now = nowLocal();
    const deal = { id: uid(), lead_id: body.lead_id, property_id: body.property_id || null, owner_id: DEMO_USER.id, value: Number(body.value), status: 'cho_duyet', closed_at: null, created_at: now };
    data.deals.push(deal);
    return deal;
  }
  m = rawPath.match(/^\/deals\/([^/]+)\/close$/);
  if (m && method === 'POST') {
    const deal = data.deals.find((d) => d.id === m[1]);
    if (!deal) throw new Error('Không tìm thấy giao dịch');
    if (deal.status === 'da_chot') throw new Error('Giao dịch đã được chốt trước đó');
    const now = nowLocal();
    deal.status = 'da_chot'; deal.closed_at = now;
    const prop = data.properties.find((p) => p.id === deal.property_id);
    if (prop) prop.status = 'da_ban';
    const lead = data.leads.find((l) => l.id === deal.lead_id);
    if (lead) { lead.status = 'ky_hd'; lead.updated_at = now; }
    data.activities.push({ id: uid(), lead_id: deal.lead_id, owner_id: DEMO_USER.id, type: 'doi_trang_thai', content: `Chốt giao dịch trị giá ${Number(deal.value).toLocaleString('vi-VN')}đ`, created_at: now });
    data.notifications.push({ id: uid(), user_id: DEMO_USER.id, title: 'Chúc mừng! Bạn vừa chốt 1 giao dịch', body: `Giá trị ${Number(deal.value).toLocaleString('vi-VN')}đ`, is_read: 0, created_at: now });
    return { ...deal };
  }
  m = rawPath.match(/^\/deals\/([^/]+)$/);
  if (m && method === 'GET') {
    const deal = data.deals.find((d) => d.id === m[1]);
    if (!deal) throw new Error('Không tìm thấy giao dịch');
    // Mock hàng đợi giữ chỗ cho deal đang giu_cho
    let queue_position = null, queue_list = [];
    if (deal.status === 'giu_cho') {
      queue_position = 1;
      queue_list = [
        { deal_id: deal.id, customer_name: (data.leads.find((l) => l.id === deal.lead_id) || {}).full_name || '—', queue_position: 1, hold_amount: 50000000, hold_expires_at: '2026-10-15 17:00:00' },
        { deal_id: 'deal-queue-2', customer_name: 'Trần Thị Bích', queue_position: 2, hold_amount: 50000000, hold_expires_at: '2026-10-16 17:00:00' },
      ];
    }
    return { ...deal, lead_name: (data.leads.find((l) => l.id === deal.lead_id) || {}).full_name, property_code: (data.properties.find((p) => p.id === deal.property_id) || {}).code, queue_position, queue_list };
  }

  // --- Notifications ---
  if (rawPath === '/notifications' && method === 'GET') {
    return [...data.notifications].sort((a, b) => b.created_at.localeCompare(a.created_at));
  }
  m = rawPath.match(/^\/notifications\/([^/]+)\/read$/);
  if (m && method === 'POST') {
    const n = data.notifications.find((x) => x.id === m[1]);
    if (n) n.is_read = 1;
    return { ok: true };
  }

  // --- Nhật ký cuộc gọi ---
  if (rawPath === '/call-logs' && method === 'GET') {
    let rows = [...data.call_logs].sort((a, b) => b.called_at.localeCompare(a.called_at));
    if (q.lead_id) rows = rows.filter((c) => c.lead_id === q.lead_id);
    return rows;
  }
  if (rawPath === '/call-logs' && method === 'POST') {
    const log = {
      id: uid(), lead_id: body.lead_id, owner_id: DEMO_USER.id, called_at: nowLocal(),
      duration_sec: Number(body.duration_sec) || 0, outcome: body.outcome || 'nghe_may',
      note: body.note || '', ai_score: null,
    };
    data.call_logs.push(log);
    return log;
  }

  // --- KPI cá nhân ---
  if (rawPath === '/kpis/summary' && method === 'GET') {
    const period = q.period === 'thang' ? 'thang' : 'tuan';
    const actual = {
      cuoc_goi: data.call_logs.length + 12,
      lich_hen: data.follow_ups.filter((f) => f.status === 'pending').length,
      dan_xem: data.activities.filter((a) => a.type === 'gap_mat').length,
      chot_deal: data.deals.filter((d) => d.status === 'da_chot').length,
    };
    const tg = kpiTargets[period];
    return {
      items: Object.keys(KPI_LABELS).map((metric) => {
        const target = tg[metric] || 0;
        return {
          metric, label: KPI_LABELS[metric],
          actual: actual[metric] || 0, target,
          percent: target > 0 ? Math.round(((actual[metric] || 0) / target) * 100) : 0,
        };
      }),
    };
  }
  if (rawPath === '/kpis/targets' && method === 'PUT') {
    (body.targets || []).forEach((t) => {
      if (kpiTargets[t.period] && KPI_LABELS[t.metric] !== undefined) {
        kpiTargets[t.period][t.metric] = Number(t.target_value) || 0;
      }
    });
    return { ok: true };
  }

  // --- Tài liệu dự án theo loại ---
  m = rawPath.match(/^\/projects\/([^/]+)\/docs$/);
  if (m && method === 'GET') {
    let rows = data.documents.filter((d) => d.project_id === m[1]);
    if (q.doc_type) rows = rows.filter((d) => (d.doc_type || 'phap_ly') === q.doc_type);
    return rows;
  }
  if (m && method === 'POST') {
    if (!body.title) throw new Error('Vui lòng nhập tiêu đề tài liệu');
    const doc = {
      id: uid(), project_id: m[1], doc_type: body.doc_type || 'phap_ly',
      title: body.title, description: body.description || '', file_url: body.file_url || '',
      created_at: nowLocal(),
    };
    data.documents.push(doc);
    return doc;
  }

  // --- Chia sẻ Zalo ---
  if (rawPath === '/share/zalo' && method === 'POST') {
    return { share_url: `https://liamhouse.demo/share/${body.type || 'lead'}/${body.id || ''}` };
  }

  // --- Nhu cầu lead (khớp nhu cầu tự động) ---
  m = rawPath.match(/^\/leads\/([^/]+)\/demand$/);
  if (m && method === 'PUT') {
    const lead = data.leads.find((l) => l.id === m[1]);
    if (!lead) throw new Error('Không tìm thấy lead');
    lead.demand_json = JSON.stringify({
      loai: body.loai || null, khu_vuc: body.khu_vuc || null,
      ngan_sach_min: body.ngan_sach_min ?? null, ngan_sach_max: body.ngan_sach_max ?? null,
      dien_tich_min: body.dien_tich_min ?? null, dien_tich_max: body.dien_tich_max ?? null,
      muc_dich: body.muc_dich || null,
    });
    lead.updated_at = nowLocal();
    return { ok: true };
  }
  m = rawPath.match(/^\/matching\/leads\/([^/]+)\/properties$/);
  if (m && method === 'GET') {
    const lead = data.leads.find((l) => l.id === m[1]);
    let demand = {};
    try { demand = lead && lead.demand_json ? JSON.parse(lead.demand_json) : {}; } catch { /* ignore */ }
    const nsMin = demand.ngan_sach_min != null ? Number(demand.ngan_sach_min) * 1e9 : null;
    const nsMax = demand.ngan_sach_max != null ? Number(demand.ngan_sach_max) * 1e9 : null;
    const dtMin = demand.dien_tich_min != null ? Number(demand.dien_tich_min) : null;
    const dtMax = demand.dien_tich_max != null ? Number(demand.dien_tich_max) : null;
    const out = [];
    for (const p of data.properties) {
      if (p.status !== 'dang_ban') continue;
      let score = 40; const reasons = [];
      if (nsMin != null && p.price >= nsMin) { score += 20; reasons.push('Trong ngân sách'); }
      else if (nsMax != null && p.price <= nsMax) { score += 20; reasons.push('Trong ngân sách'); }
      else if (nsMin == null && nsMax == null) { score += 10; }
      if (dtMin != null && p.area >= dtMin) { score += 10; reasons.push('Đủ diện tích'); }
      if (dtMax != null && p.area <= dtMax) { score += 10; reasons.push('Đúng diện tích'); }
      if (demand.khu_vuc) {
        const pj = data.projects.find((x) => x.id === p.project_id);
        if (pj && (pj.location || '').toLowerCase().includes(demand.khu_vuc.toLowerCase().slice(0, 4))) { score += 10; reasons.push('Đúng khu vực'); }
      }
      if (score >= 50) {
        const pj = data.projects.find((x) => x.id === p.project_id);
        out.push({ property: p, project_name: pj ? pj.name : '', match_score: Math.min(score, 98), match_reasons: reasons });
      }
    }
    out.sort((a, b) => b.match_score - a.match_score);
    return { data: out.slice(0, 10) };
  }

  // --- Lịch thanh toán ---
  const todayPlus = (n) => { const d = new Date(); d.setDate(d.getDate() + n); const p2 = (x) => String(x).padStart(2, '0'); return `${d.getFullYear()}-${p2(d.getMonth() + 1)}-${p2(d.getDate())}`; };
  const enrichSched = (s) => {
    const deal = data.deals.find((d) => d.id === s.deal_id) || {};
    const lead = data.leads.find((l) => l.id === deal.lead_id) || {};
    const conNo = Number(s.amount || 0) - Number(s.paid_amount || 0);
    const due = (s.due_date || '').slice(0, 10);
    const today = todayStr();
    let st = s.trang_thai_hien_tai;
    if (conNo <= 0) st = 'da_thanh_toan';
    else if (due && due < today) st = 'qua_han';
    else if (due && due <= todayPlus(10)) st = 'sap_den_han';
    else st = 'chua_den_han';
    let days = null;
    if (st === 'qua_han') {
      days = Math.round((new Date(today) - new Date(due)) / 86400000);
    }
    return { ...s, con_no: conNo, trang_thai_hien_tai: st, so_ngay_qua_han: days, deal_id: s.deal_id, lead_name: lead.full_name, lead_phone: lead.phone };
  };
  if (rawPath === '/payment-schedules/overdue' && method === 'GET') {
    return data.payment_schedules.map(enrichSched).filter((s) => s.trang_thai_hien_tai === 'qua_han');
  }
  m = rawPath.match(/^\/deals\/([^/]+)\/payment-schedules$/);
  if (m && method === 'GET') {
    return data.payment_schedules.filter((s) => s.deal_id === m[1]).sort((a, b) => a.dot_number - b.dot_number).map(enrichSched);
  }
  if (m && method === 'POST') {
    const rows = data.payment_schedules.filter((s) => s.deal_id === m[1]);
    const s = {
      id: uid(), deal_id: m[1], dot_number: rows.length + 1,
      label: body.label || `Đợt ${rows.length + 1}`,
      due_date: body.due_date ? String(body.due_date).slice(0, 10) : null,
      amount: Number(body.amount) || 0, paid_amount: 0, note: body.note || '',
    };
    data.payment_schedules.push(s);
    return enrichSched(s);
  }
  m = rawPath.match(/^\/deals\/([^/]+)\/payment-schedules\/generate$/);
  if (m && method === 'POST') {
    const deal = data.deals.find((d) => d.id === m[1]);
    const soDot = Math.max(1, Number(body.so_dot) || 1);
    const kc = Math.max(1, Number(body.khoang_cach_ngay) || 30);
    const start = body.ngay_bat_dau ? new Date(body.ngay_bat_dau) : new Date();
    const perDot = deal ? Math.round(Number(deal.value || 0) / soDot) : 0;
    const rows = data.payment_schedules.filter((s) => s.deal_id === m[1]);
    const created = [];
    for (let i = 0; i < soDot; i++) {
      const dt = new Date(start); dt.setDate(dt.getDate() + i * kc);
      const p2 = (x) => String(x).padStart(2, '0');
      const s = {
        id: uid(), deal_id: m[1], dot_number: rows.length + i + 1,
        label: `Đợt ${rows.length + i + 1}`,
        due_date: `${dt.getFullYear()}-${p2(dt.getMonth() + 1)}-${p2(dt.getDate())}`,
        amount: perDot, paid_amount: 0, note: 'Tạo tự động',
      };
      data.payment_schedules.push(s);
      created.push(enrichSched(s));
    }
    return { data: created };
  }
  m = rawPath.match(/^\/payment-schedules\/([^/]+)\/pay$/);
  if (m && method === 'PATCH') {
    const s = data.payment_schedules.find((x) => x.id === m[1]);
    if (!s) throw new Error('Không tìm thấy đợt thanh toán');
    s.paid_amount = Number(s.paid_amount || 0) + (Number(body.amount) || 0);
    return enrichSched(s);
  }
  m = rawPath.match(/^\/payment-schedules\/([^/]+)$/);
  if (m && method === 'DELETE') {
    const i = data.payment_schedules.findIndex((x) => x.id === m[1]);
    if (i < 0) throw new Error('Không tìm thấy đợt thanh toán');
    data.payment_schedules.splice(i, 1);
    return { ok: true };
  }

  // --- AI Gateway (mock) ---
  if (rawPath === '/ai/quota' && method === 'GET') {
    return {
      period: new Date().toISOString().slice(0, 7),
      plan: 'ca_nhan',
      credits_total: 500,
      credits_bonus: 0,
      credits_used: 37,
      balance: 463,
      status: 'active',
    };
  }
  if (rawPath === '/ai/quota/topup' && method === 'POST') {
    return { ok: true, added: Number(body.credits) || 100, balance: 563 };
  }
  if (rawPath === '/ai/usage-logs' && method === 'GET') {
    return [
      { id: uid(), ai_feature: 'qa_ask', credits_charged: 2, created_at: nowLocal(), cache_hit: false },
      { id: uid(), ai_feature: 'qa_ask', credits_charged: 2, created_at: nowLocal(), cache_hit: false },
    ];
  }
  if (rawPath === '/ai/ask' && method === 'POST') {
    const q = String(body.input || '').toLowerCase();
    let text;
    if (q.includes('chăm sóc') || q.includes('cham soc')) {
      const urgent = data.leads.filter((l) => ['moi', 'da_lien_he'].includes(l.status)).slice(0, 2);
      text = `Bạn có ${urgent.length} khách cần chăm sóc gấp:\n` +
        urgent.map((l, i) => `${i + 1}. ${l.full_name} (${l.phone}) — trạng thái: ${l.status}`).join('\n') +
        `\n\nGợi ý: gọi cho khách mới nhất trước, trong hôm nay.`;
    } else if (q.includes('lịch hẹn') || q.includes('lich hen') || q.includes('lịch')) {
      const pending = data.follow_ups.filter((f) => f.status === 'pending');
      text = `Hôm nay bạn có ${pending.length} lịch chăm sóc đang chờ:\n` +
        pending.slice(0, 3).map((f, i) => {
          const lead = data.leads.find((l) => l.id === f.lead_id) || {};
          return `${i + 1}. ${f.title} — ${lead.full_name || ''} (${(f.due_at || '').slice(0, 10)})`;
        }).join('\n');
    } else if (q.includes('hiệu suất') || q.includes('hieu suat') || q.includes('tuần')) {
      const s = summary();
      text = `Hiệu suất tuần này:\n• Lead mới hôm nay: ${s.leads_moi_hom_nay}\n• Follow-up đến hạn: ${s.followup_den_han}\n• Quá hạn: ${s.followup_qua_han}\n• Deal tháng: ${s.deals_thang} (${(s.doanh_so_thang / 1e9).toFixed(1)} tỷ)`;
    } else if (q.includes('thanh toán') || q.includes('thanh toan') || q.includes('deal')) {
      const overdue = data.payment_schedules.filter((s) => {
        const conNo = Number(s.amount || 0) - Number(s.paid_amount || 0);
        return conNo > 0 && s.due_date && s.due_date < todayStr();
      });
      text = overdue.length
        ? `Có ${overdue.length} đợt thanh toán quá hạn cần nhắc ngay. Vào mục "Nhắc nợ" để xem chi tiết và gọi cho khách.`
        : `Hiện không có đợt thanh toán nào quá hạn. Tuyệt vời! 🎉`;
    } else {
      text = `[Demo] Tôi đã nhận câu hỏi: "${body.input}".\n\nBản demo chưa kết nối AI thật — hãy thử các câu hỏi gợi ý như "Khách nào cần chăm sóc gấp?" để xem trả lời mẫu.`;
    }
    return { ok: true, result: { text }, credits_charged: 2, balance: 461, mock: true };
  }

  // --- Hoa hồng (demo) ---
  if (rawPath === '/commissions' && method === 'GET') {
    let rows = data.commissions || [];
    if (q.status) rows = rows.filter((c) => c.status === q.status);
    return { data: rows.map((c) => ({
      ...c,
      customer_name: (data.leads.find((l) => l.id === c.lead_id) || {}).full_name,
      property_code: (data.properties.find((p) => p.id === c.property_id) || {}).code,
    })) };
  }
  if (rawPath === '/commissions/summary' && method === 'GET') {
    const rows = data.commissions || [];
    const agg = (st) => {
      const f = rows.filter((c) => c.status === st);
      return { count: f.length, total: f.reduce((s, c) => s + Number(c.amount || 0), 0) };
    };
    return { cho_duyet: agg('cho_duyet'), da_duyet: agg('da_duyet'), da_chi: agg('da_chi') };
  }
  m = rawPath.match(/^\/commissions\/([^/]+)\/status$/);
  if (m && method === 'PATCH') {
    const c = (data.commissions || []).find((x) => x.id === m[1]);
    if (!c) throw new Error('Không tìm thấy hoa hồng');
    if (!['cho_duyet', 'da_duyet', 'da_chi'].includes(body.status)) throw new Error('Trạng thái không hợp lệ');
    c.status = body.status;
    return { ok: true, ...c };
  }
  // --- Hold queue (demo) ---
  m = rawPath.match(/^\/deals\/([^/]+)\/cancel-hold$/);
  if (m && method === 'POST') {
    const deal = data.deals.find((d) => d.id === m[1]);
    if (!deal) throw new Error('Không tìm thấy giao dịch');
    if (deal.status !== 'giu_cho') throw new Error('Giao dịch không ở trạng thái giữ chỗ');
    if (!body.cancel_reason) throw new Error('Vui lòng nhập lý do hủy');
    const now = nowLocal();
    deal.status = 'huy_giu_cho';
    deal.cancel_reason = body.cancel_reason;
    deal.updated_at = now;
    data.activities.push({ id: uid(), lead_id: deal.lead_id, owner_id: DEMO_USER.id, type: 'doi_trang_thai', content: `Hủy giữ chỗ — lý do: ${body.cancel_reason}`, created_at: now });
    return { ok: true, ...deal };
  }
  m = rawPath.match(/^\/deals\/([^/]+)\/to-deposit$/);
  if (m && method === 'POST') {
    const deal = data.deals.find((d) => d.id === m[1]);
    if (!deal) throw new Error('Không tìm thấy giao dịch');
    if (deal.status !== 'giu_cho') throw new Error('Giao dịch không ở trạng thái giữ chỗ');
    if (!body.deposit_amount || Number(body.deposit_amount) <= 0) throw new Error('Số tiền cọc không hợp lệ');
    const now = nowLocal();
    deal.status = 'dat_coc';
    deal.deposit_amount = Number(body.deposit_amount);
    deal.updated_at = now;
    data.activities.push({ id: uid(), lead_id: deal.lead_id, owner_id: DEMO_USER.id, type: 'doi_trang_thai', content: `Chuyển sang đặt cọc ${Number(body.deposit_amount).toLocaleString('vi-VN')}đ`, created_at: now });
    return { ok: true, ...deal };
  }

  throw new Error('API demo chưa hỗ trợ: ' + method + ' ' + path);
}

export const MOCK_DATA = data;
